
CREATE TABLE `dem_templates_al` (
                                    `id` int NOT NULL AUTO_INCREMENT,
                                    `code` varchar(100) NOT NULL,
                                    `name` varchar(255) NOT NULL,
                                    `category` varchar(50) DEFAULT NULL,
                                    `description` text,
                                    `operations` json NOT NULL,
                                    `is_active` tinyint(1) DEFAULT '1',
                                    `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
                                    `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                                    `systema` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
                                    `izd` varchar(50) DEFAULT NULL,
                                    `profile` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
                                    `head_name` varchar(255) DEFAULT NULL,
                                    `rules` json DEFAULT NULL,
                                    PRIMARY KEY (`id`),
                                    UNIQUE KEY `code` (`code`),
                                    KEY `idx_category` (`category`),
                                    KEY `idx_code` (`code`)
) ENGINE=InnoDB AUTO_INCREMENT=65 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

